package com.kdroid.filter;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
public class QuickAccessService extends Service {WindowManager wm;View handle;public void onCreate(){super.onCreate();show();}public int onStartCommand(Intent i,int f,int id){if(handle==null)show();return START_STICKY;}void show(){if(Build.VERSION.SDK_INT>=23&&!android.provider.Settings.canDrawOverlays(this))return;wm=(WindowManager)getSystemService(WINDOW_SERVICE);TextView v=new TextView(this);v.setText("⚙");v.setTextSize(18);v.setGravity(Gravity.CENTER);v.setBackgroundColor(0x66000000);v.setTextColor(Color.WHITE);v.setOnClickListener(x->{Intent i=new Intent(this,SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);});int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams p=new WindowManager.LayoutParams(72,72,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.END;wm.addView(v,p);handle=v;}public void onDestroy(){if(handle!=null&&wm!=null)try{wm.removeView(handle);}catch(Exception ignored){}handle=null;super.onDestroy();}public android.os.IBinder onBind(Intent i){return null;}}